"""M2a-0 T4: the opcode citation table (docs/osi/opcodes.md, generated by tools/osi/opcodes.py).

Numbers pinned here were measured on 2026-10-08 against the canonical exe and Base.osi (commit body names the commands):
256 template entries, 96 named handlers + 160 BCLUnused, 151,522 Base.osi instructions over 67 distinct opcodes.

INDEPENDENCE: `_own_handler_map` re-derives every handler address with its own few lines (PE section table -> template
dword[1] -> VM vtable slot) and takes names from symbols.txt (mangled), not from opcodes.py or functions.jsonl."""
import importlib.util
import re
import struct
from pathlib import Path

import pytest

REPO = Path(__file__).resolve().parents[2]
DOC = REPO / "docs" / "osi" / "opcodes.md"


def _load_generator():
    spec = importlib.util.spec_from_file_location("osi_opcodes", REPO / "tools" / "osi" / "opcodes.py")
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


@pytest.fixture(scope="module")
def gen():
    return _load_generator()


@pytest.fixture(scope="module")
def base_osi(lomn_data) -> Path:
    return lomn_data / "install" / "data" / "Base.osi"


@pytest.fixture(scope="module")
def rows(gen, canonical_exe, base_osi, gen_decomp):
    return gen.build_rows(canonical_exe, base_osi, gen_decomp)


# ---- an independent reader (does not import the generator) ----

def _own_handler_map(exe: Path, symbols: Path) -> dict:
    d = exe.read_bytes()
    pe = struct.unpack_from("<I", d, 0x3C)[0]
    nsec, optsz = struct.unpack_from("<H", d, pe + 6)[0], struct.unpack_from("<H", d, pe + 20)[0]
    base = struct.unpack_from("<I", d, pe + 52)[0]
    secs = [struct.unpack_from("<IIII", d, pe + 24 + optsz + 40 * i + 8) for i in range(nsec)]

    def dword(va):
        for vsize, rva, rawsize, rawptr in secs:
            if base + rva <= va < base + rva + rawsize:
                return struct.unpack_from("<I", d, rawptr + va - base - rva)[0]
        raise AssertionError("VA %#x not file-backed" % va)

    names = {}
    for line in symbols.read_text().splitlines():
        m = re.match(r"0x([0-9a-f]+) \?(BCL\w+)@ScOSIVirtualMachine@@", line)
        if m:
            names[int(m.group(1), 16)] = m.group(2)
    out = {}
    for op in range(256):
        e = 0x751768 + 16 * op
        this_delta, vtbl_off, vptr_off = dword(e), dword(e + 4), dword(e + 8)
        h = dword(0x7514E4 + vtbl_off)
        out[op] = (this_delta, vtbl_off, vptr_off, h, names.get(h))
    return out


def _own_parse_md(text: str) -> dict:
    rows, header = {}, None
    text = text.split("<!-- BEGIN opcode-table", 1)[1].split("<!-- END opcode-table", 1)[0]
    for line in text.splitlines():
        if not line.startswith("| "):
            continue
        cells = [c.strip().replace("\\|", "|") for c in re.split(r"(?<!\\)\|", line)[1:-1]]
        if header is None:
            header = cells
            continue
        if set(cells[0]) <= set("-: "):
            continue
        rows[int(cells[0], 16)] = dict(zip(header, cells))
    return rows


# ---- data-free unit tests of the generator ----

def test_regeneration_keeps_authored_cells_and_rewrites_generated(gen):
    row = {"op": "0x00", "handler": "BCLNop", "handler_addr": "0x603830", "template_entry": "0x751768",
           "vtable_slot": "6 (+0x18)", "operands": "none", "base_osi_count": "0"}
    authored = {"stack_effect": "a | b → b [0x603830]", "errors": "none [0x603830]", "notes": "kept"}
    doc = gen.update_document(None, [row], authored={0: authored})
    doc = gen.update_document(doc, [dict(row, base_osi_count="7", handler_addr="0x1")])  # authored come from doc
    again = gen.parse_table(doc)[0]
    assert (again["base_osi_count"], again["handler_addr"]) == ("7", "0x1")
    assert {k: again[k] for k in authored} == authored  # pipes survive the escape round trip


def test_prose_outside_markers_is_preserved(gen):
    row = {"op": "0x00", "handler": "BCLNop", "handler_addr": "0x603830", "template_entry": "0x751768",
           "vtable_slot": "6 (+0x18)", "operands": "none", "base_osi_count": "0"}
    doc = gen.update_document(None, [row]) + "\nAUTHORED TAIL\n"
    doc = doc.replace("# ", "# PREFIX ", 1)
    out = gen.update_document(doc, [row])
    assert "AUTHORED TAIL" in out and "# PREFIX " in out


# ---- against the real exe, Base.osi and corpus ----

def test_256_rows_96_named_160_unused(rows):
    assert [r["op"] for r in rows] == ["0x%02x" % i for i in range(256)]
    named = [r for r in rows if r["handler"] != "BCLUnused"]
    assert len(named) == 96
    assert sum(r["handler"] == "BCLUnused" for r in rows) == 160
    assert {r["handler_addr"] for r in rows if r["handler"] == "BCLUnused"} == {"0x60be60"}


@pytest.mark.parametrize("op,name,addr", [(0x82, "BCLCallGameFunction", "0x6015a0"),
                                          (0x50, "BCLJumpRelative", "0x600ae0"),
                                          (0xFF, "BCLHalt", "0x603840")])
def test_pinned_rows(rows, op, name, addr):
    assert (rows[op]["handler"], rows[op]["handler_addr"]) == (name, addr)
    assert rows[op]["template_entry"] == "0x%06x" % (0x751768 + 16 * op)


def test_base_osi_counts(rows):
    counts = [int(r["base_osi_count"]) for r in rows]
    assert sum(counts) == 151522
    assert sum(c > 0 for c in counts) == 67
    assert all(r["handler"] != "BCLUnused" for r, c in zip(rows, counts) if c)


def test_independent_handler_mapping_matches(rows, canonical_exe, gen_decomp):
    own = _own_handler_map(canonical_exe, gen_decomp / "symbols.txt")
    md = _own_parse_md(DOC.read_text())
    for op, (this_delta, vtbl_off, vptr_off, h, name) in own.items():
        # ___ptmf_scall @0x6595a0: dword[1] != -1 -> virtual call through the vptr at this + dword[0] + dword[2]
        assert (this_delta, vptr_off) == (0, 0) and vtbl_off != 0xFFFFFFFF, op
        assert name is not None, "op %#x -> %#x has no BCL symbol" % (op, h)
        for table in (rows[op], md[op]):
            assert table["handler_addr"] == "0x%x" % h, op
            assert table["handler"] == name, op
            assert table["vtable_slot"].split()[0] == str(vtbl_off // 4), op


def test_doc_generated_columns_are_current(gen, rows):
    md = _own_parse_md(DOC.read_text())
    assert sorted(md) == list(range(256))
    for r in rows:
        op = int(r["op"], 16)
        assert {k: md[op][k] for k in gen.GENERATED} == r


# Review-confirmed semantics (fix round 1), pinned as substrings of specific cells. This is a tripwire against an edit
# silently flipping a reading; the semantic gate is M2a-1's conformance suite. Each fact names its asm evidence.
PINNED_FACTS = [
    (0x78, "stack_effect", "LOGICAL shr"),                      # shr edx, cl at 0x605a76
    (0x75, "stack_effect", "unsigned div"),                     # div ecx at 0x604a9b
    (0x53, "errors", "(c.type neither 0x0f nor 0x10: float"),   # cmp 0xf / 0x10 then Error at 0x600e38
    (0x54, "stack_effect", "PC = (address after d) + d"),       # movsx + add at 0x600e9c
    (0x70, "errors", "kLenTooLong"),                            # SrThrow(0x83aa20) in append 0x4f5c9f-0x4f5ca9
    (0x82, "stack_effect", "ADDRESS OF THE ARGUMENT'S STACK SLOT"),  # *(args[i]+4) at 0x60198c-0x601abc
    (0x82, "errors", 'all end in Error("Script is calling %s.%s"'),  # .exc catch(...) 0x601cd3 -> Error 0x601dd3
    (0xB2, "stack_effect", "TRUNCATION toward zero"),           # or 0x0c00 + fistp at 0x60bc4b-0x60bc5a
]


@pytest.mark.parametrize("op,col,fact", PINNED_FACTS, ids=["%02x-%s" % (o, c) for o, c, _ in PINNED_FACTS])
def test_doc_pins_review_confirmed_facts(op, col, fact):
    assert fact in _own_parse_md(DOC.read_text())[op][col]


def test_doc_authored_cells_cite_the_handler(rows):
    md = _own_parse_md(DOC.read_text())
    for r in rows:
        if r["handler"] == "BCLUnused":
            continue
        row = md[int(r["op"], 16)]
        for col in ("stack_effect", "errors"):
            assert row[col], (r["op"], col)
            assert r["handler_addr"] in row[col], (r["op"], col, "must cite the handler address")
        assert "AMBIGUOUS" not in row["notes"] or "AMBIGUOUS:" in row["notes"], r["op"]
